WITH "m0" AS ( UPDATE "public"."mutation_item" AS "s" SET "score" = $1 , "note" = $2 FROM "public"."mutation_item" AS "b0" WHERE "s"."ctid" = "b0"."ctid" AND ( ( true AND ( ( true AND ( "s"."id" = $3 ) ) ) AND ( "s"."owner_id" = $4 ) ) ) RETURNING "s" AS "t0" , "b0"."ctid" AS "k0" , CAST(CASE WHEN "s"."score" >= $5 THEN '1' ELSE 'rusuna: permission check failed' || left( "s"."ctid" ::text, 0) END AS integer) AS "check__constraint" ), "r0" AS (SELECT ( "t0" ).* FROM "m0" ), "w0" AS (SELECT "s" .* FROM "public"."mutation_item" AS "s" WHERE NOT EXISTS ( SELECT 1 FROM "m0" WHERE "m0"."k0" = "s"."ctid" ) UNION ALL SELECT * FROM "r0" ) SELECT (SELECT row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" , "t0"."score" AS "score" , "t0"."note" AS "note" , "c3"."j" AS "owner" ) AS "%")) FROM "r0" AS "t0" LEFT JOIN LATERAL (SELECT row_to_json((SELECT "%" FROM (SELECT "t1"."id" AS "id" ) AS "%")) AS "j" FROM ( SELECT "s".* FROM "public"."mutation_author" AS "s" WHERE true AND "s"."id" = "t0"."owner_id" AND ( ( true AND ( ( true ) ) AND ( "s"."id" = $6 ) ) ) LIMIT 1 ) AS "t1" ) AS "c3" ON true )
